---
interface Props {
  current: string;
}

const { current } = Astro.props;

const nav = [
  { href: '/', label: '首页' },
  { href: '/blog', label: '文章' },
  { href: '/projects', label: '项目' },
  { href: '/about', label: '关于' },
];

const links = {
  github: 'https://github.com/JQAlpha',
  email: 'mailto:hi@jqalpha.com',
};
---

<header
  class="sticky top-0 z-50 border-b backdrop-blur-md"
  style="border-color: var(--border); background: color-mix(in srgb, var(--bg) 82%, transparent);"
>
  <div class="mx-auto flex h-16 max-w-3xl items-center justify-between px-5">
    <a href="/" class="flex items-center gap-2.5 font-medium">
      <span
        class="flex h-8 w-8 items-center justify-center rounded-lg text-sm font-semibold text-white"
        style="background: linear-gradient(135deg, #2563eb, #7c3aed);">GQ</span
      >
      <span class="hidden sm:inline">Gary Wong</span>
    </a>

    <nav class="flex items-center gap-1">
      {
        nav.map((item) => (
          <a
            href={item.href}
            class:list={[
              'rounded-lg px-3 py-1.5 text-sm transition-colors',
              current === item.href
                ? 'font-medium'
                : 'hover:bg-[var(--bg-soft)]',
            ]}
            style={current === item.href ? 'color: var(--color-accent);' : 'color: var(--text-muted);'}
            aria-current={current === item.href ? 'page' : undefined}
          >
            {item.label}
          </a>
        ))
      }
      <span class="mx-1 h-4 w-px" style="background: var(--border);"></span>
      <a
        href={links.github}
        class="rounded-lg px-2.5 py-1.5 text-sm transition-colors hover:bg-[var(--bg-soft)]"
        style="color: var(--text-muted);"
        target="_blank"
        rel="noopener noreferrer"
        aria-label="GitHub">GitHub</a
      >
    </nav>
  </div>
</header>

---
import type { CollectionEntry } from 'astro:content';

interface Props {
  post: CollectionEntry<'blog'>;
}

const { post } = Astro.props;
const { title, description, pubDate, tags = [] } = post.data;

const formatted = pubDate.toLocaleDateString('zh-CN', {
  year: 'numeric',
  month: 'long',
  day: 'numeric',
});
---

<a href={`/blog/${post.id}`} class="group block py-5">
  <div class="flex flex-col gap-1.5">
    <h3
      class="font-medium transition-colors group-hover:text-[var(--color-accent)]"
    >
      {title}
    </h3>
    <p class="text-sm leading-relaxed" style="color: var(--text-muted);">
      {description}
    </p>
    <div class="mt-1.5 flex flex-wrap items-center gap-2.5 text-xs" style="color: var(--text-faint);">
      <time datetime={pubDate.toISOString()}>{formatted}</time>
      {tags.map((tag) => <span class="tag">{tag}</span>)}
    </div>
  </div>
</a>

import { defineCollection, z } from 'astro:content';
import { glob } from 'astro/loaders';

const blog = defineCollection({
  loader: glob({ pattern: '**/*.{md,mdx}', base: './src/content/blog' }),
  schema: z.object({
    title: z.string(),
    description: z.string(),
    pubDate: z.coerce.date(),
    updatedDate: z.coerce.date().optional(),
    tags: z.array(z.string()).default([]),
    draft: z.boolean().default(false),
    cover: z.string().optional(),
    featured: z.boolean().default(false),
  }),
});

export const collections = { blog };

---
import '../styles/global.css';

interface Props {
  title?: string;
  description?: string;
  image?: string;
}

const {
  title = 'Gary Wong · 数据分析与量化研究',
  description = '专注 A 股量化研究与数据分析，记录思考、实验与代码。',
  image = '/og.png',
} = Astro.props;

const canonical = new URL(Astro.url.pathname, Astro.site);
---

<!doctype html>
<html lang="zh-CN">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>{title}</title>
    <meta name="description" content={description} />
    <link rel="canonical" href={canonical} />
    <link rel="icon" type="image/svg+xml" href="/favicon.svg" />
    <link rel="sitemap" href="/sitemap-index.xml" />
    <link rel="alternate" type="application/rss+xml" title="Gary Wong" href="/rss.xml" />
    <meta name="generator" content={Astro.generator} />

    <meta property="og:type" content="website" />
    <meta property="og:url" content={canonical} />
    <meta property="og:title" content={title} />
    <meta property="og:description" content={description} />
    <meta property="og:image" content={new URL(image, Astro.site)} />
    <meta property="og:site_name" content="Gary Wong" />

    <meta name="twitter:card" content="summary_large_image" />
    <meta name="twitter:title" content={title} />
    <meta name="twitter:description" content={description} />
    <meta name="twitter:image" content={new URL(image, Astro.site)} />

    <meta name="theme-color" content="#2563eb" media="(prefers-color-scheme: light)" />
    <meta name="theme-color" content="#0b1120" media="(prefers-color-scheme: dark)" />

    <script is:inline>
      (function () {
        var t = localStorage.getItem('theme');
        if (t === 'dark') document.documentElement.style.colorScheme = 'dark';
      })();
