  </head>
  <body>
    <slot />
  </body>
</html>

---
import { getCollection, render } from 'astro:content';
import Header from '../../components/Header.astro';
import BaseLayout from '../../layouts/BaseLayout.astro';

export async function getStaticPaths() {
  const posts = await getCollection('blog', ({ data }) => !data.draft);
  return posts.map((post) => ({
    params: { slug: post.id },
    props: { post },
  }));
}

const { post } = Astro.props;
const { Content } = await render(post);

const { title, description, pubDate, updatedDate, tags = [] } = post.data;

const formatted = pubDate.toLocaleDateString('zh-CN', {
  year: 'numeric',
  month: 'long',
  day: 'numeric',
});
---

<BaseLayout title={`${title} · Gary Wong`} description={description}>
  <Header current="/blog" />

  <main class="mx-auto max-w-3xl px-5 py-14">
    <article>
      <a
        href="/blog"
        class="mb-6 inline-flex items-center gap-1.5 text-sm transition-colors"
        style="color: var(--text-faint);"
      >
        ← 返回文章列表
      </a>

      <header class="mb-9">
        <h1 class="text-2xl font-medium leading-snug sm:text-3xl">{title}</h1>
        <p class="mt-3 text-lg" style="color: var(--text-muted);">{description}</p>
        <div
          class="mt-5 flex flex-wrap items-center gap-3 text-sm"
          style="color: var(--text-faint);"
        >
          <time datetime={pubDate.toISOString()}>{formatted}</time>
          {
            updatedDate && (
              <span>
                更新于{' '}
                {updatedDate.toLocaleDateString('zh-CN', {
                  year: 'numeric',
                  month: 'long',
                  day: 'numeric',
                })}
              </span>
            )
          }
          {tags.map((tag) => <span class="tag">{tag}</span>)}
        </div>
      </header>

      <div class="prose-body">
        <Content />
      </div>
    </article>

    <div
      class="mt-14 flex items-center justify-between border-t pt-6 text-sm"
      style="border-color: var(--border); color: var(--text-faint);"
    >
      <a href="/blog" class="transition-colors hover:text-[var(--text)]">← 全部文章</a>
      <a href="mailto:hi@jqalpha.com" class="transition-colors hover:text-[var(--text)]"
        >有问题？写信给我</a
      >
    </div>
  </main>
</BaseLayout>

---
import { getCollection } from 'astro:content';
import Header from '../../components/Header.astro';
import PostCard from '../../components/PostCard.astro';
import BaseLayout from '../../layouts/BaseLayout.astro';

const posts = (await getCollection('blog', ({ data }) => !data.draft)).sort(
  (a, b) => b.data.pubDate.valueOf() - a.data.pubDate.valueOf()
);

const tags = [...new Set(posts.flatMap((p) => p.data.tags))];
---

<BaseLayout title="文章 · Gary Wong" description="量化研究、数据分析与可视化相关的文章与实验记录。">
  <Header current="/blog" />

  <main class="mx-auto max-w-3xl px-5 py-14">
    <header class="mb-10">
      <h1 class="text-2xl font-medium sm:text-3xl">文章</h1>
      <p class="mt-3" style="color: var(--text-muted);">
        量化研究、数据分析与可视化相关的思考与实验记录。
      </p>
      {
        tags.length > 0 && (
          <div class="mt-5 flex flex-wrap gap-2">
            {tags.map((tag) => (
              <span class="tag">{tag}</span>
            ))}
          </div>
        )
      }
    </header>

    {
      posts.length === 0 ? (
        <div class="card p-10 text-center" style="color: var(--text-muted);">
          <p class="text-lg">还没有文章</p>
          <p class="mt-2 text-sm" style="color: var(--text-faint);">
            在 <code>src/content/blog/</code> 下添加一个 .md 文件，push 后会自动发布。
          </p>
        </div>
      ) : (
        <div class="divide-y" style="border-color: var(--border);">
          {posts.map((post) => (
            <PostCard post={post} />
          ))}
        </div>
      )
    }
  </main>
</BaseLayout>

import rss from '@astrojs/rss';
import { getCollection } from 'astro:content';
import type { APIContext } from 'astro';

export async function GET(context: APIContext) {
  const posts = (await getCollection('blog', ({ data }) => !data.draft)).sort(
    (a, b) => b.data.pubDate.valueOf() - a.data.pubDate.valueOf()
  );

  return rss({
    title: 'Gary Wong',
    description: '量化研究与数据分析——思考、实验与代码',
    site: context.site ?? 'https://jqalpha.com',
    items: posts.map((post) => ({
      title: post.data.title,
      description: post.data.description,
      pubDate: post.data.pubDate,
      link: `/blog/${post.id}/`,
      categories: post.data.tags,
    })),
    customData: '<language>zh-cn</language>',
  });
}

@import "tailwindcss";

@theme {
  --font-sans: "Inter", "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
  --font-mono: "JetBrains Mono", "SF Mono", Consolas, monospace;

  --color-accent: #2563eb;
  --color-accent-hover: #1d4ed8;
}

:root {
  color-scheme: light dark;
  --bg: #ffffff;
  --bg-soft: #f8fafc;
  --bg-elevated: #ffffff;
  --border: #e2e8f0;
  --border-strong: #cbd5e1;
  --text: #0f172a;
  --text-muted: #64748b;
  --text-faint: #94a3b8;
  --shadow: 0 1px 2px rgb(15 23 42 / 0.04), 0 4px 12px rgb(15 23 42 / 0.04);
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0b1120;
    --bg-soft: #0f172a;
    --bg-elevated: #111c33;
    --border: #1e293b;
    --border-strong: #334155;
    --text: #e2e8f0;
    --text-muted: #94a3b8;
    --text-faint: #64748b;
    --shadow: 0 1px 2px rgb(0 0 0 / 0.3), 0 4px 12px rgb(0 0 0 / 0.2);
  }
}

html {
  scroll-behavior: smooth;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  transition: background-color 0.2s ease, color 0.2s ease;
}

::selection {
  background: rgb(37 99 235 / 0.18);
}

a {
  transition: color 0.15s ease;
}

.card {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: 12px;
  box-shadow: var(--shadow);
}

.prose-body {
  color: var(--text);
  line-height: 1.8;
  font-size: 1.0625rem;
}

.prose-body h2 {
  font-size: 1.4rem;
  font-weight: 500;
  margin-top: 2.4em;
  margin-bottom: 0.8em;
  padding-bottom: 0.35em;
  border-bottom: 1px solid var(--border);
}

.prose-body h3 {
  font-size: 1.15rem;
  font-weight: 500;
  margin-top: 1.8em;
  margin-bottom: 0.6em;
}

.prose-body p {
  margin: 1.1em 0;
}

.prose-body a {
  color: var(--color-accent);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.prose-body ul,
.prose-body ol {
  margin: 1.1em 0;
  padding-left: 1.5em;
}

.prose-body li {
  margin: 0.45em 0;
}

.prose-body li::marker {
  color: var(--text-faint);
}

.prose-body code {
  font-family: var(--font-mono);
  font-size: 0.875em;
  background: var(--bg-soft);
  border: 1px solid var(--border);
  border-radius: 5px;
  padding: 0.15em 0.4em;
}

.prose-body pre {
  background: var(--bg-soft);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 1.1rem 1.25rem;
  overflow-x: auto;
  margin: 1.4em 0;
  line-height: 1.6;
}

.prose-body pre code {
  background: transparent;
  border: none;
  padding: 0;
  font-size: 0.85rem;
}

.prose-body blockquote {
  border-left: 3px solid var(--color-accent);
  padding-left: 1.1rem;
  margin: 1.4em 0;
  color: var(--text-muted);
  font-style: normal;
}

.prose-body table {
  width: 100%;
  border-collapse: collapse;
  margin: 1.4em 0;
  font-size: 0.9375rem;
}

.prose-body th,
.prose-body td {
  border: 1px solid var(--border);
  padding: 0.6rem 0.85rem;
  text-align: left;
}

.prose-body th {
  background: var(--bg-soft);
  font-weight: 500;
}

.prose-body img {
  border-radius: 10px;
  border: 1px solid var(--border);
}

.tag {
  display: inline-block;
  font-size: 0.75rem;
  padding: 0.15rem 0.6rem;
  border-radius: 999px;
  background: var(--bg-soft);
  border: 1px solid var(--border);
  color: var(--text-muted);
}
